(()=>{'use strict';const $=s=>document.querySelector(s),esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),KEY='common-ground-v1',copy=v=>JSON.parse(JSON.stringify(v));let initial=Emergence.create(),world=copy(initial),runs=[],notes='',label='',log=[],busy=false,controller=null,playing=false,selected=null;
try{const saved=JSON.parse(localStorage.getItem(KEY));if(saved){validate(saved);({initial,world,notes,label,runs,log}=saved);}}catch(e){$('#status').textContent='Previous run could not be loaded. Import an exported run to recover it.';}
function validate(x){if(x?.world?.format!=='emergence-world'||x.world.version!==1||x.initial?.format!=='emergence-world'||!Array.isArray(x.world.journal)||x.world.journal.length>2000)throw Error('Unsupported run');const replay=Emergence.replay(x.initial,x.world.journal);if(JSON.stringify(replay)!==JSON.stringify(x.world))throw Error('Run failed deterministic replay validation');}
function save(){try{localStorage.setItem(KEY,JSON.stringify({initial,world,runs,notes,label,log}));}catch(e){$('#status').textContent='Save failed: '+e.message+'. Export this run now.';}}
function show(html){$('#detail').innerHTML=html;$('#dialog').showModal();}$('#close').onclick=()=>$('#dialog').close();
function render(){const m=Emergence.metrics(world);$('#turn').textContent='TURN '+String(world.turn).padStart(3,'0');$('#metrics').innerHTML=Object.entries(m).map(([k,v])=>'<div class="metric"><b>'+v+'</b><span>'+esc(k)+'</span></div>').join('');$('#map').innerHTML=Array.from({length:96},(_,i)=>{const x=i%12,y=Math.floor(i/12),site=world.sites.find(s=>s.x===x&&s.y===y),jar=world.objects.find(o=>o.x===x&&o.y===y&&o.holder===null);return '<div class="cell '+(site?.kind||'')+'" title="'+x+','+y+(site?' · '+site.name+' '+site.stock+'/'+site.capacity:'')+'">'+(site?'<span>'+(site.kind==='water'?'◉':'✳')+'</span>':'')+(jar?'<span>▱</span>':'')+world.agents.filter(a=>a.alive&&a.x===x&&a.y===y).map(a=>'<button class="person" data-person="'+a.id+'" title="'+esc(a.name)+'">'+a.name[0]+'</button>').join('')+'</div>';}).join('');$('#people').innerHTML=world.agents.map(a=>'<div class="agent" data-person="'+a.id+'"><strong>'+a.name+'</strong> <small>'+(!a.alive?'DECEASED':a.x+','+a.y)+'</small><div class="bars">'+[a.food/40,a.water/40,a.energy/100].map(v=>'<div class="bar"><i style="width:'+Math.min(100,v*100)+'%"></i></div>').join('')+'</div><div class="last">'+esc(a.last)+'</div></div>').join('');document.querySelectorAll('[data-person]').forEach(el=>el.onclick=()=>{selected=Number(el.dataset.person);const a=world.agents.find(a=>a.id===selected);show('<h2>'+esc(a.name)+'</h2><p>Food '+a.food+' · Water '+a.water+' · Energy '+a.energy+' · Health '+a.health+'</p><h3>Personal objective</h3><p>'+esc(a.goal||'No objective stated')+'</p><h3>Private record</h3>'+a.memory.slice().reverse().map(m=>'<p><small>Turn '+m.turn+' · '+esc(m.kind)+'</small><br>'+esc(m.from?m.from+': ':'')+esc(m.text)+'</p>').join(''));});$('#events').innerHTML=world.events.slice(-50).reverse().map(e=>'<div class="event '+e.kind+'"><small>TURN '+e.turn+' · '+esc(world.agents.find(a=>a.id===e.actor)?.name||'WORLD')+' · '+e.kind.toUpperCase()+'</small>'+esc(e.text)+'</div>').join('')||'<p>No events yet. Advance a turn to begin.</p>';$('#label').value=label;$('#notes').value=notes;$('#comparisons').innerHTML=runs.slice(-5).map(r=>'<p class="small">'+esc(r.label)+' · seed '+r.seed+' · '+r.scarcity+' · turn '+r.metrics.turn+' · alive '+r.metrics.alive+' · transfers '+r.metrics.transfers+'</p>').join('');$('#chart').innerHTML='<span class="small">RESOURCE STOCK · WATER / FOOD</span><svg viewBox="0 0 400 70" aria-label="Current water and food stock"><rect x="0" y="10" width="'+world.sites[0].stock/18*400+'" height="15" fill="#729ca9"/><rect x="0" y="40" width="'+world.sites[1].stock/18*400+'" height="15" fill="#789663"/></svg>';$('#step').disabled=busy;$('#new').disabled=busy;$('#import').disabled=busy;$('#cancel').hidden=!busy;$('#play').textContent=playing?'Pause':'Run';}
async function step(){if(busy)return;if(!world.agents.some(a=>a.alive)){playing=false;$('#status').textContent='The population has died. Inspect the record or start a comparison run.';render();return;}busy=true;controller=new AbortController();const snapshot=copy(world),entries={};$('#status').textContent='Individuals are deciding from their private observations…';render();try{const outcome=await TurnKernel.collect(world.agents.filter(a=>a.alive),async(a,signal)=>{const req={actor:a.id,view:Emergence.view(snapshot,a.id)},started=Date.now();try{const url=new URL(window.INHABITANT_API_URL);url.pathname='/api/sandbox';const res=await fetch(url,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(req),signal});const raw=await res.text();log.push({turn:world.turn,actor:a.id,ms:Date.now()-started,status:res.status,response:raw.slice(0,6000)});if(!res.ok)throw Error(JSON.parse(raw).error||'Model unavailable');return JSON.parse(raw).command;}catch(e){log.push({turn:world.turn,actor:a.id,error:e.message});throw e;}},(v,a)=>({actor:a.id,command:Emergence.command(v)}),{signal:controller.signal,deadlineMs:15000,onFault:f=>entries[f.actor]={error:f.reason}});
if(!outcome.commands.length&&outcome.faults.every(f=>f.failureKind!=='invalid-response'))throw Error('All model requests failed. Run paused without consuming a turn. The backend must support /api/sandbox.');for(const r of outcome.commands)entries[r.actor]=r.command;for(const f of outcome.faults)delete entries[f.actor];world=Emergence.step(snapshot,entries,crypto.randomUUID());log=log.slice(-150);$('#status').textContent='Turn '+world.turn+' committed · '+outcome.commands.length+' accepted actions · '+outcome.faults.length+' missing actions. No referee calls.';save();}catch(e){playing=false;$('#status').textContent=e.name==='AbortError'?'Cancelled. No turn consumed.':e.message;}finally{busy=false;controller=null;render();if(playing)setTimeout(step,1500);}}
$('#step').onclick=step;$('#play').onclick=()=>{playing=!playing;render();if(playing)step();};$('#cancel').onclick=()=>controller?.abort();$('#new').onclick=()=>{if(world.turn)runs.push({label:label||'Unlabelled',seed:initial.seed,scarcity:initial.scarcity,metrics:Emergence.metrics(world)});initial=Emergence.create(Number($('#seed').value)||42,$('#scarcity').value);world=copy(initial);label='';notes='';log=[];playing=false;save();render();$('#status').textContent='New experiment ready. No social roles or cooperation instructions are assigned.';};$('#export').onclick=()=>{const blob=new Blob([JSON.stringify({initial,world,runs,notes,label,log},null,2)],{type:'application/json'}),a=document.createElement('a'),url=URL.createObjectURL(blob);a.href=url;a.download='common-ground-turn-'+world.turn+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);};$('#import').onchange=async e=>{try{playing=false;const x=JSON.parse(await e.target.files[0].text());validate(x);({initial,world}=x);runs=x.runs||[];notes=x.notes||'';label=x.label||'';log=x.log||[];save();render();$('#status').textContent='Imported and replay-verified.';}catch(e){$('#status').textContent='Import rejected: '+e.message;}};$('#replay').onclick=()=>{try{validate({initial,world});$('#status').textContent='Replay matches exactly. No model requests were made.';}catch(e){$('#status').textContent=e.message;}};$('#label').oninput=e=>{label=e.target.value;save();};$('#notes').oninput=e=>{notes=e.target.value;save();};$('#rules').onclick=()=>show('<h2>A small world with stable rules</h2><p>Each turn permits one action and optional speech. Movement covers at most two tiles. Drinking or eating one stock unit restores five reserve units, capped at 40. Everyone spends one food, water and energy per turn. Empty food causes four health damage; empty water causes six. Rest restores up to 18 energy before upkeep.</p><p>The spring and grove are finite shared stocks. Every third turn they renew by six units in forgiving conditions, or two in scarce conditions, up to capacity 18. A person carries up to eight food and one jar. Jars hold eight water. Fill at the spring; pour for a neighbour. Giving and pouring require distance at most one. Speech is heard within two tiles. Action priority rotates each turn.</p><p>Agents see only nearby people, sites and objects, their own body and their own bounded memory. Starting reserves allow 30 turns before deprivation. No trade, group, leader or cooperative behaviour is scripted. Rules stay fixed during each run. Transfer and speech counts do not establish emergence.</p>');render();})();
